const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Apanha os dados de entrada do n8n
const items = $input.all();
const dadosEntrada = items[0].json;

// Se os dados estiverem dentro de um array ou propriedade específica, ajustamos:
const listaInvestimentos = Array.isArray(dadosEntrada) 
  ? dadosEntrada 
  : (dadosEntrada.investimentos || dadosEntrada.data || []);

// Mensagens estáticas baseadas no perfil (MVP)
const templatesMensagem = {
  "Conservador": "Olá! Com base no seu perfil Conservador, preparamos uma seleção com foco em renda fixa e segurança para proteger o seu patrimônio.",
  "Moderado": "Olá! Com base no seu perfil Moderado, selecionamos um mix equilibrado entre renda fixa e variável para potenciar os seus ganhos com controlo de risco.",
  "Arrojado": "Olá! Com base no seu perfil Arrojado, destacamos oportunidades com ênfase em ações e maior potencial de retorno para o longo prazo."
};

// Agrupar os produtos por perfil
const agrupadosPorPerfil = {};

listaInvestimentos.forEach(item => {
  const perfil = item.perfil || "Moderado";
  if (!agrupadosPorPerfil[perfil]) {
    agrupadosPorPerfil[perfil] = {
      perfil: perfil,
      mensagem: templatesMensagem[perfil] || "Aqui estão as opções de investimento recomendadas para o seu perfil.",
      produtos: []
    };
  }

  agrupadosPorPerfil[perfil].produtos.push({
    produto: item.produto,
    minimo: item.minimo,
    rentabilidade: item.rentabilidade
  });
});

// Converter o objeto agrupado de volta para o formato de array aceitado pelo n8n
const resultadoFinal = Object.values(agrupadosPorPerfil).map(grupo => {
  return { json: grupo };
});

return resultadoFinal;
